        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ("col", c)
                break
    if divider is None:
        return out

    # The object consists of non-background, non-divider cells.
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 2]
    if not obj:
        return out

    r0 = min(r for r, c in obj)
    r1 = max(r for r, c in obj)
    c0 = min(c for r, c in obj)
    c1 = max(c for r, c in obj)

