        height = r1 - r0 + 1
        if r1 < d:
            new_r0 = d - height
            line = new_r0 - 1
        else:
            new_r0 = d + 1
            line = new_r0 + height
        dr = new_r0 - r0

        for r, c in obj:
            out[r][c] = bg
        for r, c in obj:
            out[r + dr][c] = grid[r][c]
        if 0 <= line < h:
